const clock = new THREE.Clock();
scene.background = new THREE.Color(0xf4f7fb);
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.08;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const keyLight = new THREE.DirectionalLight(0xffffff, 1.35);
keyLight.position.set(6, 10, 8);
keyLight.castShadow = true;
keyLight.shadow.mapSize.width = 2048;
keyLight.shadow.mapSize.height = 2048;
const fillLight = new THREE.DirectionalLight(0xbfd7ff, 0.55);
fillLight.position.set(-7, 4, 5);
const rimLight = new THREE.PointLight(0xaad6ff, 0.45, 22);
rimLight.position.set(-4, 3, -5);
scene.add(new THREE.AmbientLight(0x7f8aa6, 0.32), keyLight, fillLight, rimLight);

const floor = new THREE.Mesh(
  new THREE.CircleGeometry(12, 96),
  new THREE.MeshStandardMaterial({ color: 0xe6ecf5, roughness: 0.92, metalness: 0.02 })
);
floor.rotation.x = -Math.PI / 2;
floor.position.y = -2.5;
floor.receiveShadow = true;
scene.add(floor);

const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true;
controls.dampingFactor = 0.05;
controls.minDistance = 3;
controls.maxDistance = 15;

const entityGroup = new THREE.Group();
scene.add(entityGroup);

const coreGeometry = new THREE.IcosahedronGeometry(1.2, 2);
const coreMaterial = new THREE.MeshPhysicalMaterial({
  color: 0x4a90e2,
  metalness: 0.1,
  roughness: 0.05,
  transmission: 0.6,
  thickness: 1.5,
  ior: 1.7,
  clearcoat: 1,
  clearcoatRoughness: 0.1,
  emissive: 0x2d5a9e,
  emissiveIntensity: 0.2
});
const core = new THREE.Mesh(coreGeometry, coreMaterial);
core.castShadow = true;
entityGroup.add(core);

const innerGlow = new THREE.Mesh(
  new THREE.IcosahedronGeometry(0.8, 1),
  new THREE.MeshBasicMaterial({ color: 0x7bb3f0, transparent: true, opacity: 0.3, wireframe: true })
);
entityGroup.add(innerGlow);

const orbitGroups = [];
const orbitConfigs = [
  { radius: 2.5, speed: 0.5, count: 3, scale: 0.3, geometry: new THREE.OctahedronGeometry(0.4, 0) },
  { radius: 3.8, speed: 0.3, count: 5, scale: 0.2, geometry: new THREE.TetrahedronGeometry(0.3, 0) },
  { radius: 5.2, speed: 0.2, count: 8, scale: 0.15, geometry: new THREE.BoxGeometry(0.4, 0.4, 0.4) }
];

const satelliteMaterial = new THREE.MeshPhysicalMaterial({
  color: 0xffffff,
  metalness: 0.8,
  roughness: 0.2,
  clearcoat: 0.8,
  iridescence: 1,
  iridescenceIOR: 1.3
});

orbitConfigs.forEach((config, layerIndex) => {
  const group = new THREE.Group();
  for (let i = 0; i < config.count; i++) {
    const angle = (i / config.count) * Math.PI * 2;
    const mesh = new THREE.Mesh(config.geometry, satelliteMaterial);
    mesh.position.set(
      Math.cos(angle) * config.radius,
      Math.sin(layerIndex) * 0.8,
      Math.sin(angle) * config.radius
    );
    mesh.scale.setScalar(config.scale);
    mesh.castShadow = true;
    mesh.userData = { 
      basePos: mesh.position.clone(), 
      phase: angle,
      speed: config.speed,
      layer: layerIndex
    };
    group.add(mesh);
  }
  group.userData = { speed: config.speed * 0.2, axis: new THREE.Vector3(0, 1, 0) };
  orbitGroups.push(group);
  entityGroup.add(group);
});

const connectionMaterial = new THREE.LineBasicMaterial({ 
  color: 0xaad6ff, 
  transparent: true, 
  opacity: 0.4,
  linewidth: 1
});
const connections = new THREE.Group();
entityGroup.add(connections);

function updateConnections(time) {
  while(connections.children.length > 0) {
    connections.remove(connections.children[0]);
  }

  orbitGroups.forEach((group, idx) => {
    group.children.forEach((satellite, i) => {
      if (i < group.children.length - 1) {
        const next = group.children[i + 1];
        const points = [satellite.position.clone(), next.position.clone()];
        const geometry = new THREE.BufferGeometry().setFromPoints(points);
        const line = new THREE.Line(geometry, connectionMaterial);
        connections.add(line);
      }

      const coreLinePoints = [satellite.position.clone(), core.position.clone()];
      const coreLineGeom = new THREE.BufferGeometry().setFromPoints(coreLinePoints);
      const coreLine = new THREE.Line(coreLineGeom, connectionMaterial);
      coreLine.material.opacity = 0.15 + Math.sin(time * 2 + satellite.userData.phase) * 0.1;
      connections.add(coreLine);
    });
  });
}

const particleCount = 200;
const particleGeometry = new THREE.BufferGeometry();
const positions = new Float32Array(particleCount * 3);
const velocities = [];

for (let i = 0; i < particleCount; i++) {
  const r = 6 + Math.random() * 4;
  const theta = Math.random() * Math.PI * 2;
  const phi = Math.acos(2 * Math.random() - 1);
  positions[i * 3] = r * Math.sin(phi) * Math.cos(theta);
  positions[i * 3 + 1] = r * Math.sin(phi) * Math.sin(theta);
  positions[i * 3 + 2] = r * Math.cos(phi);
  velocities.push({
    x: (Math.random() - 0.5) * 0.01,
    y: (Math.random() - 0.5) * 0.01,
    z: (Math.random() - 0.5) * 0.01,
    phase: Math.random() * Math.PI * 2
  });
}
particleGeometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));

const particleMaterial = new THREE.PointsMaterial({
  color: 0x6b9dc7,
  size: 0.08,
  transparent: true,
  opacity: 0.6,
  sizeAttenuation: true
});
const particles = new THREE.Points(particleGeometry, particleMaterial);
entityGroup.add(particles);

const ambientRings = [];
for (let i = 0; i < 3; i++) {
  const ring = new THREE.Mesh(
    new THREE.TorusGeometry(2 + i * 1.5, 0.02, 16, 100),
    new THREE.MeshBasicMaterial({ 
      color: 0xc8ddf0, 
      transparent: true, 
      opacity: 0.15 - i * 0.03 
    })
  );
  ring.rotation.x = Math.PI / 2;
  ring.rotation.y = i * 0.5;
  ambientRings.push(ring);
  entityGroup.add(ring);
}

camera.position.set(4.4, 2.4, 5.2);
camera.lookAt(0, 0, 0);

function animate() {
  requestAnimationFrame(animate);
  const t = clock.getElapsedTime();
  const delta = clock.getDelta();

  controls.update();

  core.rotation.y = t * 0.1;
  core.rotation.z = t * 0.05;
  innerGlow.rotation.y = -t * 0.2;
  innerGlow.rotation.x = Math.sin(t * 0.3) * 0.2;

  coreMaterial.emissiveIntensity = 0.2 + Math.sin(t * 1.5) * 0.1;
  innerGlow.material.opacity = 0.2 + Math.sin(t * 2) * 0.1;

  orbitGroups.forEach((group, idx) => {
    group.rotation.y += group.userData.speed * 0.02;
    group.children.forEach((satellite, i) => {
      const data = satellite.userData;
      const bob = Math.sin(t * data.speed + data.phase) * 0.2;
      satellite.position.y = data.basePos.y + bob;
      satellite.rotation.x += 0.01;
      satellite.rotation.y += 0.015;
    });
  });

  updateConnections(t);

  const positions = particles.geometry.attributes.position.array;
  for (let i = 0; i < particleCount; i++) {
    const v = velocities[i];
    positions[i * 3] += Math.sin(t * 0.5 + v.phase) * 0.002;
    positions[i * 3 + 1] += Math.cos(t * 0.3 + v.phase) * 0.002;
    positions[i * 3 + 2] += Math.sin(t * 0.4 + v.phase) * 0.002;
  }
  particles.geometry.attributes.position.needsUpdate = true;
  particles.rotation.y = t * 0.02;

  ambientRings.forEach((ring, i) => {
    ring.rotation.x = Math.PI / 2 + Math.sin(t * 0.2 + i) * 0.1;
    ring.rotation.z = t * (0.05 + i * 0.02);
  });

  rimLight.intensity = 0.35 + Math.sin(t * 1.2) * 0.08;
  fillLight.intensity = 0.55 + Math.cos(t * 0.8) * 0.05;

  entityGroup.position.y = Math.sin(t * 0.4) * 0.15;

  renderer.render(scene, camera);
}
animate();

